package com.google.javascript.rhino;

import com.google.javascript.rhino.JSDocInfo.Visibility;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.Set;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.util.reflection.FieldReader;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import org.mockito.internal.util.reflection.FieldReader; // Note: In a real environment, use standard reflection if FieldReader is not available

public class JSDocInfoBuilder_recordBlockDescription_TriageGen2Test {

    /**
     * Helper to set the private field 'currentInfo' using reflection 
     * since it is required for the method to function.
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    /**
     * Mock interface for currentInfo based on the method call currentInfo.documentBlock(description)
     */
    private interface MockDocumentBlocker {
        boolean documentBlock(String description);
    }

    @Test
    public void testRecordBlockDescription_WithParseDocumentationTrue_ReturnsTrue() throws Exception {
        // Arrange
        JSDocInfoBuilder builder = new JSDocInfoBuilder(true);
        MockDocumentBlocker mockInfo = mock(MockDocumentBlocker.class);
        setPrivateField(builder, "currentInfo", mockInfo);

        String description = "Test Description";
        when(mockInfo.documentBlock(description)).thenReturn(true);

        // Act
        boolean result = builder.recordBlockDescription(description);

        // Assert
        assertTrue("Result should be true when documentBlock returns true", result);
        assertTrue("populated should be true when parseDocumentation is true", builder.isPopulated());
    }

    @Test
    public void testRecordBlockDescription_WithParseDocumentationTrue_ReturnsFalse() throws Exception {
        // Arrange
        JSDocInfoBuilder builder = new JSDocInfoBuilder(true);
        MockDocumentBlocker mockInfo = mock(MockDocumentBlocker.class);
        setPrivateField(builder, "currentInfo", mockInfo);

        String description = "Test Description";
        when(mockInfo.documentBlock(description)).thenReturn(false);

        // Act
        boolean result = builder.recordBlockDescription(description);

        // Assert
        assertFalse("Result should be false when documentBlock returns false", result);
        assertTrue("populated should be true when parseDocumentation is true", builder.isPopulated());
    }

    @Test
    public void testRecordBlockDescription_WithParseDocumentationFalse_ReturnsTrue() throws Exception {
        // Arrange
        JSDocInfoBuilder builder = new JSDocInfoBuilder(false);
        MockDocumentBlocker mockInfo = mock(MockDocumentBlocker.class);
        setPrivateField(builder, "currentInfo", mockInfo);

        String description = "Test Description";
        when(mockInfo.documentBlock(description)).thenReturn(true);

        // Act
        boolean result = builder.recordBlockDescription(description);

        // Assert
        assertTrue("Result should be true when documentBlock returns true", result);
        assertFalse("populated should remain false when parseDocumentation is false", builder.isPopulated());
    }

    @Test
    public void testRecordBlockDescription_WithParseDocumentationFalse_ReturnsFalse() throws Exception {
        // Arrange
        JSDocInfoBuilder builder = new JSDocInfoBuilder(false);
        MockDocumentBlocker mockInfo = mock(MockDocumentBlocker.class);
        setPrivateField(builder, "currentInfo", mockInfo);

        String description = "Test Description";
        when(mockInfo.documentBlock(description)).thenReturn(false);

        // Act
        boolean result = builder.recordBlockDescription(description);

        // Assert
        assertFalse("Result should be false when documentBlock returns false", result);
        assertFalse("populated should remain false when parseDocumentation is false", builder.isPopulated());
    }
}
